const {chromium}=require(process.env.PLAYWRIGHT_PATH||'playwright');
const assert=require('node:assert/strict');
(async()=>{const browser=await chromium.launch({headless:true,executablePath:process.env.CHROME_PATH});const page=await browser.newPage();const errors=[];page.on('pageerror',e=>errors.push(e.message));await page.goto('http://localhost:4173');
for(const [width,height] of [[1707,898],[1280,720],[390,844],[844,390]]){await page.setViewportSize({width,height});await page.waitForTimeout(100);const size=await page.evaluate(()=>{let r=document.querySelector('.screen').getBoundingClientRect();return {width:r.width,height:r.height,center:Math.abs(r.x+r.width/2-innerWidth/2),overflow:document.documentElement.scrollWidth>innerWidth};});assert(Math.abs(size.width/size.height-16/9)<.02);assert(size.center<2);assert(!size.overflow);console.log('PASS responsive '+width+'×'+height+' '+JSON.stringify(size));}
await page.setViewportSize({width:1707,height:898});await page.click('#fullscreen');await page.waitForTimeout(200);const full=await page.evaluate(()=>{const r=document.querySelector('.screen').getBoundingClientRect(),c=document.querySelector('canvas').getBoundingClientRect();return {fullscreen:!!document.fullscreenElement,width:r.width,height:r.height,x:r.x,y:r.y,canvasWidth:c.width,canvasHeight:c.height,viewportWidth:innerWidth,viewportHeight:innerHeight};});assert(full.fullscreen);assert.equal(full.x,0);assert.equal(full.y,0);assert.equal(full.width,full.viewportWidth);assert.equal(full.height,full.viewportHeight);assert(full.canvasWidth>=full.width*.9);assert(full.canvasHeight>=full.height*.9);assert(Math.abs(full.canvasWidth/full.canvasHeight-16/9)<.02);console.log('PASS fullscreen '+JSON.stringify(full));await page.screenshot({path:__dirname+'/preview-fullscreen.png'});await page.evaluate(()=>document.exitFullscreen());await page.screenshot({path:__dirname+'/preview-desktop.png',fullPage:true});assert.deepEqual(errors,[]);console.log('PASS no browser runtime errors');await browser.close();})().catch(e=>{console.error(e);process.exit(1);});
